INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, sources, last_checked)
SELECT id, 'software_engineer', 'fresher', '[{"name": "Pre-presentation", "format": "Session led by TCS HR at some colleges", "tests": "Salary, career growth and company culture, followed by Q&A", "duration": null}, {"name": "Written test", "format": "Online, elimination round", "tests": "Foundation section (numerical, verbal, reasoning); advanced section (advanced reasoning and coding) for Digital and Prime aspirants", "duration": "Reported 190 minutes in total"}, {"name": "Technical panel", "format": "Interview", "tests": "Technical knowledge and problem solving", "duration": "25 to 40 minutes across the three panels"}, {"name": "Managerial panel", "format": "Interview", "tests": "Leadership potential through situational and behavioural questions", "duration": null}, {"name": "HR panel", "format": "Interview", "tests": "Soft skills, communication, cultural fit and motivation", "duration": null}]'::jsonb, '["strings", "arrays", "oop_principles", "sql_fundamentals"]'::jsonb, 'Round order and the pre-presentation depend on the drive. The invitation is the reference.', 'The written test is the main filter and is mostly aptitude, with a longer coding section only for the higher tracks. The interview is reported as one sitting with technical, managerial and HR panels. The pre-presentation is not held at every college.', NULL, '[{"url": "https://www.placementpreparation.io/tcs-nqt/recruitment-process", "title": "TCS NQT recruitment process (placementpreparation.io)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'tcs';

