INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, sources, last_checked)
SELECT id, 'software_engineer', 'fresher', '[{"name": "Resume screening", "format": "Initial shortlist", "tests": "Eligibility against the role", "duration": null}, {"name": "Online assessment", "format": "Online, six sections", "tests": "Logical reasoning, mathematical ability, verbal ability, pseudocode (Specialist Programmer and Digital Specialist Engineer), numerical puzzle, one essay", "duration": "Section times listed as 25, 35, 20, 10, 10 and 20 minutes"}, {"name": "Technical interview", "format": "Interview", "tests": "Programming concepts, data structures and algorithms, DBMS and SQL, operating systems, networking, past projects", "duration": "25 to 40 minutes"}, {"name": "HR interview", "format": "Interview", "tests": "Soft skills, communication, cultural fit, background and motivation", "duration": null}]'::jsonb, '["oop_principles", "sql_fundamentals", "operating_systems_basics", "networking_basics", "arrays"]'::jsonb, 'Pseudocode applies to Specialist Programmer and Digital Specialist Engineer roles.', 'Four stages are described. The source is inconsistent about the total test time (a 90 minute statement against section times that add up to 120), so check the drive notice. The technical interview is reported to cover basics and projects rather than hard puzzles.', NULL, '[{"url": "https://www.placementpreparation.io/infosys/recruitment-process/", "title": "Infosys recruitment process (placementpreparation.io)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'infosys';

