SELECT id, 'software_engineer', 'fresher', '[{"name": "Online test", "format": "Online, three sections", "tests": "Aptitude, written communication, online programming", "duration": "Reported 128 minutes: 48 aptitude, 20 written communication, 60 programming"}, {"name": "Technical interview", "format": "Interview", "tests": "Technical fundamentals", "duration": null}, {"name": "HR interview", "format": "Interview", "tests": "Fit and motivation", "duration": null}]'::jsonb, '[]'::jsonb, 'Only the stages and test timings are sourced. Interview content is not.', 'Only the general shape is sourced: an online test, a technical interview and an HR interview. The source gives section timings for the test but no detail on the interview content.', NULL, '[{"url": "https://cpt.hitbullseye.com/wipro-elite-nlth-exam-pattern-and-syllabus.php", "title": "Wipro Elite NTH exam pattern (hitbullseye)"}]'::jsonb, '2026-10-15'
