SELECT id, 'software_engineer', 'fresher', '[{"name": "Cognitive and technical assessment", "format": "Online, proctored multiple choice", "tests": "Verbal, critical and abstract reasoning, pseudocode, networking, database and object-oriented basics", "duration": null}, {"name": "Coding round", "format": "Online", "tests": "Two programming problems on basic logic with arrays, strings and numbers", "duration": "About 45 minutes"}, {"name": "Communication assessment", "format": "Online spoken English test", "tests": "Reading aloud, repeating audio, reordering sentences and retelling a story", "duration": "About 30 minutes"}, {"name": "Interview", "format": "Video call, often one combined session", "tests": "Technical questions on data structures, queries, OS, OOP and projects, then HR questions", "duration": null}]'::jsonb, '["arrays", "strings", "oop_principles", "sql_fundamentals", "operating_systems_basics", "networking_basics"]'::jsonb, 'Treat the invitation email for the drive as the authority on order.', 'Described as four stages whose order can differ between drives. The coding problems are reported as basic, and candidates advise fully solving one rather than partly solving both. Experienced hires are reported to get a recruiter call, a technical interview and an HR conversation instead.', NULL, '[{"url": "https://www.designgurus.io/answers/detail/what-is-the-accenture-interview-process-like-round-by-round", "title": "Accenture interview process round by round (designgurus.io)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'accenture';

